<script>
document.addEventListener('DOMContentLoaded',function(){var attrs=@json($attributes->keyBy('id')),csrf='{{ csrf_token() }}',base='{{ url('/catalog-attributes') }}';
function modal(id,open){document.getElementById(id).classList.toggle('open',open)}document.querySelectorAll('[data-open]').forEach(function(b){b.onclick=function(){if(b.dataset.open==='create-modal'&&!batchList.querySelector('.ca-batch-row'))addBatchRow();modal(b.dataset.open,true)}});document.querySelectorAll('.ca-close,.ca-close-button').forEach(function(b){b.onclick=function(){b.closest('.ca-modal').classList.remove('open')}});document.querySelectorAll('.ca-modal').forEach(function(m){m.onclick=function(e){if(e.target===m)m.classList.remove('open')}});
function options(s){var f=s.closest('form').querySelector('.ca-options-field');if(f)f.style.display=s.value!=='text'?'block':'none'}document.querySelectorAll('.ca-input-type').forEach(function(s){s.onchange=function(){options(s)};options(s)});
document.querySelectorAll('.ca-edit').forEach(function(b){b.onclick=function(){var a=attrs[b.dataset.id],f=document.getElementById('edit-form');f.action=base+'/'+a.id;document.getElementById('edit-category').value=a.category_id;document.getElementById('edit-name').value=a.name;document.getElementById('edit-type').value=a.input_type;document.getElementById('edit-order').value=a.display_order;document.getElementById('edit-options').value=JSON.parse(a.options||'[]').join('\n');document.getElementById('edit-filter').checked=+a.is_filterable===1;document.getElementById('edit-compare').checked=+a.is_comparable===1;options(document.getElementById('edit-type'));modal('edit-modal',true)}});
document.querySelectorAll('.ca-category-head').forEach(function(h){h.onclick=function(){var b=h.nextElementSibling;b.style.display=b.style.display==='none'?'block':'none';h.querySelector('.icon-chevron-down').classList.toggle('icon-chevron-right')}});var expanded=true;document.getElementById('expand-all').onclick=function(){expanded=!expanded;document.querySelectorAll('.ca-category-body').forEach(function(b){b.style.display=expanded?'block':'none'});this.innerHTML=expanded?'<i class="icon-resize-small icon-white"></i> Collapse all':'<i class="icon-resize-full icon-white"></i> Expand all'};
function refreshChecks(){if(window.jQuery&&jQuery.uniform&&jQuery.uniform.update)jQuery.uniform.update('.select-attribute,.select-group')}function selected(){var n=document.querySelectorAll('.select-attribute:checked').length;document.getElementById('selected-count').textContent=n;document.getElementById('bulk-bar').classList.toggle('show',n>0);document.querySelectorAll('.select-group').forEach(function(group){var boxes=group.closest('table').querySelectorAll('.select-attribute'),checked=group.closest('table').querySelectorAll('.select-attribute:checked').length;group.checked=boxes.length>0&&checked===boxes.length;group.indeterminate=checked>0&&checked<boxes.length});refreshChecks()}document.querySelectorAll('.select-attribute').forEach(function(c){c.onchange=selected});document.querySelectorAll('.select-group').forEach(function(c){c.onchange=function(){var state=c.checked;c.closest('table').querySelectorAll('.select-attribute').forEach(function(x){x.checked=state});selected()}});document.getElementById('clear-selection').onclick=function(){document.querySelectorAll('.select-attribute,.select-group').forEach(function(c){c.checked=false;c.indeterminate=false});selected()};selected();
var dragged=null;document.querySelectorAll('.ca-table tbody tr').forEach(function(row){row.ondragstart=function(){dragged=row;row.classList.add('dragging')};row.ondragend=function(){row.classList.remove('dragging');document.querySelectorAll('.drag-over').forEach(function(r){r.classList.remove('drag-over')});saveOrder(row.closest('.ca-category'))};row.ondragover=function(e){e.preventDefault();if(row!==dragged){row.classList.add('drag-over');var box=row.getBoundingClientRect();row.parentNode.insertBefore(dragged,e.clientY<box.top+box.height/2?row:row.nextSibling)}};row.ondragleave=function(){row.classList.remove('drag-over')}});
function saveOrder(section){var ids=Array.prototype.map.call(section.querySelectorAll('tbody tr'),function(r){return r.dataset.id}),data=new FormData();data.append('_token',csrf);data.append('category_id',section.dataset.category);ids.forEach(function(id){data.append('attribute_ids[]',id)});fetch(base+'/reorder',{method:'POST',body:data,credentials:'same-origin'}).then(function(r){if(!r.ok)throw Error();return r.json()}).then(function(){toast('Order saved')}).catch(function(){toast('Could not save order')})}function toast(t){var e=document.getElementById('ca-toast');e.textContent=t;e.style.display='block';setTimeout(function(){e.style.display='none'},1800)}
var batchIndex=0,batchList=document.getElementById('batch-list');function updateBatch(){var rows=batchList.querySelectorAll('.ca-batch-row');document.getElementById('batch-count').textContent=rows.length+' attribute'+(rows.length===1?'':'s')+' ready';document.getElementById('save-batch').disabled=rows.length===0;rows.forEach(function(row,i){row.querySelector('.ca-row-number').textContent='Attribute '+(i+1)})}function addBatchRow(focus){var i=batchIndex++,row=document.createElement('div');row.className='ca-batch-row';row.innerHTML='<div class="ca-row-number"></div><div class="ca-batch-row-head"><div class="ca-field" style="margin:0"><label>Attribute name</label><input name="attributes['+i+'][name]" placeholder="Example: Memory Capacity" required></div><div class="ca-field" style="margin:0"><label>Input type</label><select name="attributes['+i+'][input_type]" class="batch-input-type"><option value="select">Select list</option><option value="multiselect">Multiple select</option><option value="text">Free text</option></select></div><div class="ca-field" style="margin:0"><label>Order</label><input type="number" min="0" name="attributes['+i+'][display_order]" value="'+((batchList.querySelectorAll('.ca-batch-row').length+1)*10)+'"></div><button type="button" class="btn ca-remove-row"><i class="icon-trash"></i> Remove</button></div><div class="ca-batch-options"><label>Options <small>(one per line)</small></label><textarea name="attributes['+i+'][options]" placeholder="Option one&#10;Option two"></textarea></div><div class="ca-checks" style="margin-top:10px"><label><input type="checkbox" name="attributes['+i+'][is_filterable]" value="1" checked> Store filter</label><label><input type="checkbox" name="attributes['+i+'][is_comparable]" value="1" checked> Comparison</label></div>';var type=row.querySelector('.batch-input-type'),optionBox=row.querySelector('.ca-batch-options');type.onchange=function(){optionBox.style.display=type.value!=='text'?'block':'none'};row.querySelector('.ca-remove-row').onclick=function(){row.remove();updateBatch()};batchList.appendChild(row);updateBatch();if(focus!==false)row.querySelector('input').focus()}document.getElementById('add-batch-row').onclick=function(){addBatchRow(true)};document.getElementById('add-five-rows').onclick=function(){for(var i=0;i<5;i++)addBatchRow(i===4)};document.getElementById('clear-batch').onclick=function(){if(batchList.children.length&&confirm('Remove every unsaved row from this batch?')){batchList.innerHTML='';updateBatch()}};document.getElementById('batch-create-form').onsubmit=function(){if(!batchList.querySelector('.ca-batch-row')){addBatchRow(true);return false}return confirm('Create all '+batchList.querySelectorAll('.ca-batch-row').length+' attributes in this batch?')};updateBatch();
});
</script>
@endsection
